// Normalise Nigerian numbers to WhatsApp-style international format (e.g. 2348031234567)
function normPhone(p) {
  if (!p) return null;
  let d = String(p).replace(/\D/g, '');
  if (d.startsWith('0') && d.length === 11) d = '234' + d.slice(1);
  if (d.length === 10 && /^[789]/.test(d)) d = '234' + d;
  return d || null;
}
function normEmail(e) {
  if (!e) return null;
  const s = String(e).trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s) ? s : null;
}
// Our own unique ID for every message, whatever the channel: msg_<time>_<random>
function newId() {
  return 'msg_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
}

// WhatsApp (simulated Cloud API webhook OR n8n WhatsApp Trigger) -> Unified Message Schema (v2)
// Works with both shapes, so swapping the Webhook for the real WhatsApp Trigger later needs no changes here.
return $input.all().map(item => {
  const j = item.json;
  const v = j.body?.entry?.[0]?.changes?.[0]?.value
         ?? j.entry?.[0]?.changes?.[0]?.value
         ?? j;
  const msg = v.messages?.[0];
  const contact = v.contacts?.[0] ?? {};
  if (!msg) {
    // Delivery/read receipts arrive without a message - flag and let the IF node drop them
    return { json: { schema_version: 2, channel: 'whatsapp', is_valid: false,
      missing_fields: ['message'], note: 'status update, no customer message' } };
  }
  const phone = normPhone(msg.from || contact.wa_id);
  let text = '';
  if (msg.type === 'text') text = msg.text?.body ?? '';
  else if (msg.type === 'button') text = msg.button?.text ?? '';
  else if (msg.type === 'interactive') text = msg.interactive?.button_reply?.title ?? msg.interactive?.list_reply?.title ?? '';
  else text = `[${msg.type} message]`;
  text = String(text).trim();
  const ts = Number(msg.timestamp);
  return { json: {
    schema_version: 2,
    message_id: newId(),
    channel_message_id: msg.id || null,
    channel: 'whatsapp',
    channel_user_id: phone,
    thread_id: phone,
    customer: { name: contact.profile?.name || null, email: null, phone },
    subject: null,
    message_text: text,
    message_type: msg.type || 'text',
    received_at: ts ? new Date(ts * 1000).toISOString() : new Date().toISOString(),
    is_valid: text.length > 0 && !!phone,
    missing_fields: [!text && 'message', !phone && 'phone'].filter(Boolean),
    meta: { business_phone_id: v.metadata?.phone_number_id || null, simulated: !!j.body }
  }};
});

// Phase 9 · Duplicate protection: the same channel message (same WhatsApp wamid / email Message-ID) is processed only once
const store = $getWorkflowStaticData('global');           // kept by n8n between production runs
store.seen = Array.isArray(store.seen) ? store.seen : [];
return $input.all().map(item => {
  const id = item.json.channel_message_id;
  const is_duplicate = !!id && store.seen.includes(id);
  if (id && !is_duplicate) {
    store.seen.push(id);
    if (store.seen.length > 1000) store.seen = store.seen.slice(-1000);   // remember the last 1,000
  }
  return { json: { ...item.json, is_duplicate } };
});
